use sqlx::{MySql,Pool};use uuid::Uuid;pub async fn run(pool:&Pool<MySql>)->anyhow::Result<()>{let (uc,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM users").fetch_one(pool).await?;if uc==0{let now=chrono::Utc::now().naive_utc();for (n,e) in [("Alice","alice@example.com"),("Bob","bob@example.com")] {sqlx::query("INSERT INTO users (id,name,email,created_at,updated_at) VALUES (?,?,?,?,?)").bind(Uuid::new_v4()).bind(n).bind(e).bind(now).bind(now).execute(pool).await?;}}let (pc,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM products").fetch_one(pool).await?;if pc==0{let now=chrono::Utc::now().naive_utc();for (n,p) in [("Widget",1299_i64),("Gadget",2499_i64),("Thing",799_i64)] {sqlx::query("INSERT INTO products (id,name,price_cents,created_at,updated_at) VALUES (?,?,?,?,?)").bind(Uuid::new_v4()).bind(n).bind(p).bind(now).bind(now).execute(pool).await?;}}Ok(())}
